// lz-compress: greedy LZ77 over a generated byte buffer (see lz-compress.mi).

#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

namespace {

std::vector<std::uint8_t> generated_input(std::size_t n) {
    std::vector<std::uint8_t> data;
    data.reserve(n);
    std::int64_t state = 11;
    while (data.size() < n) {
        state = state * 48271 % 2147483647;
        if (data.size() > 64 && state % 4 == 0) {
            const std::size_t back = 1 + static_cast<std::size_t>((state / 4) % 60);
            const std::int64_t length = 3 + (state / 256) % 20;
            for (std::int64_t k = 0; k < length && data.size() < n; k++) {
                data.push_back(data[data.size() - back]);
            }
        } else {
            data.push_back(static_cast<std::uint8_t>(97 + state % 16));
        }
    }
    return data;
}

std::string kernel(std::int64_t n) {
    const auto data = generated_input(static_cast<std::size_t>(n));
    const std::size_t size = data.size();
    std::int64_t literals = 0, matches = 0, hash = 0;
    std::size_t pos = 0;
    while (pos < size) {
        std::size_t best_length = 0, best_distance = 0;
        for (std::size_t start = pos > 255 ? pos - 255 : 0; start < pos; start++) {
            std::size_t length = 0;
            while (pos + length < size && length < 255 && data[start + length] == data[pos + length]) {
                length++;
            }
            if (length > best_length) {
                best_length = length;
                best_distance = pos - start;
            }
        }
        if (best_length >= 3) {
            matches += 1;
            hash = (hash * 31 + static_cast<std::int64_t>(best_distance * 256 + best_length)) % 1000000007;
            pos += best_length;
        } else {
            literals += 1;
            hash = (hash * 31 + data[pos]) % 1000000007;
            pos += 1;
        }
    }
    return std::to_string(literals) + " " + std::to_string(matches) + " " + std::to_string(hash);
}

std::string run_hot(std::int64_t n) {
    const std::string expected = kernel(n);
    bool agree = true;
    for (int i = 1; i < 5; i++) {
        const std::string checksum = kernel(n);
        agree = agree && checksum == expected;
    }
    for (int i = 0; i < 5; i++) {
        const auto start = std::chrono::steady_clock::now();
        const std::string checksum = kernel(n);
        const auto elapsed = std::chrono::steady_clock::now() - start;
        std::cerr << "hot_ns=" << std::chrono::duration_cast<std::chrono::nanoseconds>(elapsed).count() << "\n";
        agree = agree && checksum == expected;
    }
    if (!agree) {
        std::cerr << "checksum differs between iterations\n";
        std::exit(1);
    }
    return expected;
}

}  // namespace

int main(int argc, char **argv) {
    std::ifstream input(argv[1]);
    std::int64_t n = 0;
    if (!(input >> n)) {
        return 2;
    }
    const bool hot = argc > 2 && std::string(argv[2]) == "hot";
    std::cout << (hot ? run_hot(n) : kernel(n)) << "\n";
    return 0;
}
